class Solution {
public:
    int prev = -1, best = INT_MAX;
    void walk(TreeNode* node) {
        if (!node) return;
        walk(node->left);
        if (prev >= 0) best = min(best, node->val - prev);
        prev = node->val;
        walk(node->right);
    }
    int getMinimumDifference(TreeNode* root) {
        walk(root);
        return best;
    }
};
